    db: &'db dyn TypeDb,
    members: Vec<TypeMember<'db>>,
) -> TypeData<'db> {
    object_from_members(
        db,
        members
            .into_iter()
            .map(|mut member| {
                let was_optional = member.kind.is_optional();
