        write!(f, [token("[")])?;
        let types = format_with(|f| {
            let separator =
                format_with(|f| write!(f, [&format_args![token(","), soft_line_break_or_space()]]));
            let mut joiner = f.join_with(separator);
            for ty in self.0 {
                joiner.entry(&format_args![ty]);
            }
            joiner.finish()
        });
        write!(
            f,
            [&format_args![group(&soft_block_indent(&types)), token("]")]]
        )
    }
}

